package com.example.starter.incident;

/**
 * 在场凭证状态机：ACTIVE 当前有效 → SUPERSEDED（本人重新签到）/ REVOKED（当前指挥撤销）
 * / FROZEN（任务完成时与另一份同时冻结）。除 ACTIVE 外均为不可用状态。
 * 凭证是否在有效期内还需结合 issued_at/expires_at 按左闭右开区间判断。
 */
public enum AttendanceStatus {

    /** 当前代次有效；是否在 60 秒有效期内另按签发/到期时刻判断。 */
    ACTIVE,

    /** 被本人重新签到推进取代的历史代次，永久失效。 */
    SUPERSEDED,

    /** 被当前指挥人撤销，永久失效。 */
    REVOKED,

    /** 任务 DONE 时冻结；签发与到期时刻固定保留，作为首次完成证据。 */
    FROZEN;
}

package com.example.starter.incident;

import java.time.Instant;

/**
 * 任务双人监护配置实体，对应 task_guardians 表。每个任务至多一条；
 * guardianOne/guardianTwo 为固定的两个不同合成操作者，启用后不可更换；
 * version 为监护配置版本，启用时从 1 开始，完成时必须显式引用该期望版本。
 * 时间均为 UTC。
 */
public record TaskGuardian(
        long id,
        long taskId,
        String guardianOne,
        String guardianTwo,
        int version,
        String createdBy,
        Instant createdAt) {

    /**
     * 判断操作者是否为被固定的监护人之一。
     */
    public boolean isGuardian(String actor) {
        return guardianOne.equals(actor) || guardianTwo.equals(actor);
    }
}

package com.example.starter.incident;

import java.time.Instant;

/**
 * 限时在场凭证实体，对应 task_attendance 表。
 * 每个 (taskId, guardian, generation) 唯一：同一监护人每次签到代次 generation 加 1，
 * 从 1 开始；有效期为 [issuedAt, expiresAt)，长度 60 秒，左闭右开，时刻均为 UTC。
 * status 见 {@link AttendanceStatus}；revokedAt 仅 REVOKED 有值，其余状态为空。
 */
public record TaskAttendance(
        long id,
        long taskId,
        String guardian,
        int generation,
        Instant issuedAt,
        Instant expiresAt,
        AttendanceStatus status,
        Instant revokedAt,
        Instant createdAt) {

    /**
     * 以给定 UTC 时刻判断凭证是否处于有效区间 [issuedAt, expiresAt)（左闭右开）。
     */
    public boolean validAt(Instant now) {
        return !now.isBefore(issuedAt) && now.isBefore(expiresAt);
    }
}

