                requireCommander(incident, actor);
                IncidentTask task = tasks.findByKey(incident.id(), taskKey)
                        .orElseThrow(() -> ApiException.notFound("任务不存在: " + taskKey));
                if (task.status() != TaskStatus.OPEN) {
