479	    /**
480	     * 完成任务：仅当前指挥人；仅 OPEN 可完成；全部阻塞事件进入
481	     * CONTAINED/RESOLVED/CLOSED 后才可完成，否则 409 并返回未解除事件列表。
482	     * 启用双人监护的任务必须显式引用监护配置期望版本与双方当前凭证代次：
483	     * 两份凭证均 ACTIVE 且处于 [issuedAt, expiresAt) 才转 DONE，同事务冻结双方凭证；
484	     * 缺失、过期、旧代次、版本不符均 422，任务与凭证均不改变。
485	     * DONE/CANCELLED 为终态，重复操作按 commandKey 幂等规则返回首次结果；
486	     * 指挥权校验先于重放，越权调用方不能借重放读取首次响应。
487	     */
488	    @Transactional
489	    public TaskView completeTask(String incidentKey, String taskKey, String actor,
490	                                 TaskCompleteRequest req) {
491	        String commandKey = requireText(req.commandKey(), "commandKey");
492	        Incident incident = lockIncident(incidentKey);
493	        requireCommander(incident, actor);
494	        String requestHash = hash(incidentKey, taskKey, actor,
495	                req.expectedVersion() == null ? "" : Integer.toString(req.expectedVersion()),
496	                normalizeRefs(req.attendances()));
497	        return runIdempotent(commandKey, "task_complete", requestHash, TaskView.class, () -> {
498	            IncidentTask task = tasks.findByKey(incident.id(), taskKey)
499	                    .orElseThrow(() -> ApiException.notFound("任务不存在: " + taskKey));
500	            if (task.status() != TaskStatus.OPEN) {
501	                throw ApiException.conflict(
502	                        "任务已处于终态 " + task.status() + "，不能完成");
503	            }
504	            TaskGuardian guardian = guardians.findByTaskId(task.id()).orElse(null);
505	            List<TaskAttendance> frozen = guardian == null ? List.of()
506	                    : verifyGuardAttendance(task, guardian, req);
507	            List<String> unresolved = unresolvedBlockers(task.id());
508	            if (!unresolved.isEmpty()) {
509	                throw ApiException.conflict("存在未解除阻塞的事件: "
510	                        + String.join(",", unresolved), List.copyOf(unresolved));
511	            }
512	            Instant doneAt = now();
513	            tasks.markDone(task.id(), actor, doneAt);
514	            for (TaskAttendance attendance : frozen) {
515	                int updated = guardians.freezeGeneration(task.id(), attendance.guardian(),
516	                        attendance.generation());
517	                if (updated != 1) {
518	                    // 行锁内不应发生：凭证边界在校验后被改动，保守回滚
519	                    throw ApiException.illegalTransition("在场凭证已失效，不能完成");
520	                }
521	            }
522	            return toTaskView(tasks.findByKey(incident.id(), taskKey).orElseThrow());
523	        });
524	    }
